pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        // restrict to non-zero positive amount that fit in balance
        vm.assume(amount > 0 && amount < type(uint128).max);
        address referenceTarget = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        uint256 balanceBefore = referenceTarget.balance;

        address sender = address(0x1234);
        vm.deal(sender, amount);
        vm.prank(sender);
        c.go{value: amount}();

        // Property: The reference target's balance must increase by exactly the sent amount.
        // In the reference, the call goes to the hardcoded address. In the buggy version,
        // the call goes to address(0), so referenceTarget.balance stays unchanged.
        assertTrue(referenceTarget.balance == balanceBefore + amount);
    }
}

