pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow but keep it wide
        amount = bound(amount, 0, type(uint128).max);
        address actor = address(0x1337);
        vm.deal(actor, amount);
        vm.deal(address(c), 1 ether); // pre-fund c with some balance
        uint256 ownerBalanceBefore = c.owner().balance;
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(actor);
        c.go{value: amount}();
        // After go(), the contract balance must be 0 and the owner must receive the previous contract balance
        // (which included the pre-funded balance and the sent amount).
        assertTrue(
            address(c).balance == 0 &&
            c.owner().balance == ownerBalanceBefore + contractBalanceBefore
        );
    }
}

