pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Restrict amount to the admissible domain: avoid overflow and ensure contract can receive ETH.
        vm.assume(amount > 0 && amount <= address(this).balance);
        // 2. Fund the contract directly (simulate prior balance) and then call go() with msg.value.
        vm.deal(address(c), amount);
        vm.deal(address(this), amount);
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        uint256 targetBalBefore = target.balance;
        c.go{value: amount}();
        // 3. The target should have received exactly msg.value (amount), not the contract's entire balance.
        assertTrue(target.balance - targetBalBefore == amount);
    }
}

