pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // keep amount reasonable and caller distinct from owner to avoid trivial transfer-to-self issues
        amount = bound(amount, 1, address(this).balance / 2);
        vm.assume(caller != c.owner());
        vm.assume(caller != address(c));
        vm.assume(caller != address(this));

        uint256 ownerBefore = c.owner().balance;
        vm.deal(caller, amount);
        vm.prank(caller);
        // the target 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C must be an EOA for the call to succeed
        // we prerecord it as a non-zero, non-precompile address; fuzzing it would give an EOA, which is fine
        try c.go{value: amount}() {
            // success: reference always transfers remaining balance to owner, mutant transfers to msg.sender
            uint256 ownerAfter = c.owner().balance;
            // owner must have received at least amount (call to target succeeded, then transfer to owner)
            assertTrue(ownerAfter >= ownerBefore + amount);
        } catch {
            // if the target call fails, the whole transaction reverts – nothing to assert
        }
    }
}

