pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance / 2);
        vm.deal(address(this), amount * 2);
        bool ok;
        try c.go{value: amount}() { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}
// helper contract to force external call to fail: deployed and used by making target = address(failer) if needed, but target is hardcoded in C. Since C has a hardcoded target and the fuzzer cannot change it, we cannot inject an adversarial callee. The rule only holds when the hardcoded target succeeds, which is always the case for a call with sufficient gas to a regular address. To detect the bug, we rely on the fact that the hardcoded address 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C is either an EOA or a contract that accepts ETH successfully (low-level call to EOA always succeeds). Therefore the call always succeeds and we check balance == 0 after. The bug leaves balance > 0 for any nonzero amount.

