pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        address sender = makeAddr("sender");
        vm.deal(sender, amount);
        vm.prank(sender);

        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || address(c).balance == 0, "balance must be zero after successful go");
    }
}

